VID.narration = {"look":{"bar":false},"scenes":[{"dur":10.96,"caps":[[0.5,9.23,"Lecture two. Why evolutionary algorithms. This is about optimisation, and problems too hard to solve exactly."]],"warp":[[0,0],[0.5,0.9],[10.96,4]]},{"dur":31.672,"caps":[[0.5,5.39,"Three items. Aim for 100 kg in total."],[5.64,11.49,"Bits: 1 takes an item, 0 leaves it."],[11.74,17.35,"Fitness f(s): how far from 100 kg. Smaller is better."],[17.6,23.61,"Exhaustive search: try every subset."],[23.86,30.91,"Try all 8: 110 is the best, with f = 5."]],"warp":[[0,0],[0.5,0.3],[5.64,2.6],[11.74,5],[17.6,8],[23.86,9.9],[31.672,12]]},{"dur":21.78,"caps":[[0.5,4.19,"3 items make 8 possible solutions."],[4.44,7.41,"Each extra item doubles the count."],[7.66,13.91,"A real water network: 21 pipes, 16 sizes each."],[14.16,20.73,"Trying every design takes 600 million years."]],"warp":[[0,0],[0.5,0.3],[4.44,2.6],[7.66,6.3],[14.16,8.7],[21.78,12]]},{"dur":28.328,"caps":[[0.5,7.15,"A tiny exponential against a polynomial."],[7.4,13.65,"At n = 44 the exponential overtakes."],[13.9,20.55,"Now a real run, with a bigger exponential."],[20.8,27.69,"Microseconds for a polynomial, years for an exponential."]],"warp":[[0,0],[0.5,0.4],[7.4,3.2],[13.9,6.6],[20.8,8.4],[28.328,11]]},{"dur":24.892,"caps":[[0.5,7.15,"Connect all 5 towns as cheaply as possible."],[7.4,11.73,"Prim: take the cheapest cable to a new town."],[11.98,16.39,"Keep adding the cheapest cable. No loops."],[16.64,22.73,"Fast and always optimal: an easy problem."]],"warp":[[0,0],[0.5,0.3],[7.4,2.2],[11.98,5.4],[16.64,9.2],[24.892,12]]},{"dur":33.321,"caps":[[0.5,5.39,"New rule: at most 2 cables per town."],[5.64,11.57,"But the best tree has 3 cables at C."],[11.82,16.15,"Run the same greedy method again."],[16.4,22.01,"An early cheap choice blocks cheaper ones later."],[22.26,31.71,"Greedy gets 20, but a tree costing 19 exists."]],"warp":[[0,0],[0.5,0.3],[5.64,1.6],[11.82,3],[16.4,5.6],[22.26,9.2],[33.321,12]]},{"dur":30.023,"caps":[[0.5,6.03,"Nearest neighbour: an instant, decent tour."],[6.28,12.13,"The EA starts from random tangles."],[12.38,16.63,"It keeps improving its best tour."],[16.88,22.01,"Given time, it overtakes the quick method."],[22.26,28.35,"Approximate: good answers, no guarantee."]],"warp":[[0,0],[0.5,0.4],[6.28,2.8],[12.38,4.4],[16.88,6.2],[22.26,10.2],[30.023,13]]},{"dur":23.429,"caps":[[0.5,7.39,"A population: 10 solutions, each with a fitness."],[7.64,13.89,"Select: fitter ones are more likely, not only the best."],[14.14,18.87,"Vary: children can be better or worse."],[19.12,22.41,"Next: who stays?"]],"warp":[[0,0],[0.5,0.4],[7.64,2.4],[14.14,5],[19.12,8.6],[23.429,11]]},{"dur":25.101,"caps":[[0.5,5.55,"Replace everyone: the old best can be lost."],[5.8,12.69,"Merge, keep the best 10: the best survives."],[12.94,20.31,"Replace the weakest: the best survives too."],[20.56,23.85,"Then repeat the loop."]],"warp":[[0,0],[0.5,0.8],[5.8,4.2],[12.94,8.7],[20.56,10.5],[25.101,12]]},{"dur":16.881,"caps":[],"warp":[[0,0],[0.5,0.9],[4.2,2.1],[7.9,3.3],[16.881,9]]}]};
